at::Tensor BmmKernelCambricon(const at::Tensor& self, const at::Tensor& mat2) {
  const at::ScalarType dtype = at::result_type(self, mat2);
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: bmm does not serve ", dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1 &&
          mat2.device() == self.device(),
      "flagos cambricon: bmm needs both operands on one device");
  TORCH_CHECK(
      self.dim() == 3 && mat2.dim() == 3 && self.size(0) == mat2.size(0),
      "flagos cambricon: bmm expects two 3-D operands with one batch size");
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const bool widen = ComputesInFloat32(dtype);
  // A transposed operand is described, not copied. `x @ w.t()` is how every
  // Linear layer spells its product, and materialising that view copies the
  // whole weight on every call: measured at 1024x3072, mm(x, w.t()) took 9027 us
  // against 37 us for mm(x, w) -- 242 times slower for the same arithmetic.
  // CNNL expresses it with CNNL_MATMUL_DESC_TRANS* plus the operand's own
  // strides, so both are passed through instead of being normalised away.
  // This is the shape `x @ w.t()` takes in every Linear layer, and copying the
  // weight there made the multiply 242 times slower than the same product on a
  // contiguous operand.
  // A 2-D view whose transpose is contiguous is described by that storage plus
  // the matmul transpose flag; anything else is materialised.
  const bool a_transposed =
      self.dim() == 2 && !self.is_contiguous() && self.t().is_contiguous();
  const bool b_transposed =
      mat2.dim() == 2 && !mat2.is_contiguous() && mat2.t().is_contiguous();
  // With the transpose flag set, CNNL expects each descriptor to describe the
  // operand's *storage*, and applies the transpose itself. So a transposed
  // operand is passed as the contiguous view whose transpose is the logical
  // matrix -- for `w.t()` that view is `w`. The result shape still follows aten's
  // rules, which is why it is computed from the logical operands.
  const auto a = a_transposed ? self.t() : self.contiguous();
  const auto b = b_transposed ? mat2.t() : mat2.contiguous();
  const auto aw = widen ? Widen(a, handle) : a;
  const auto bw = widen ? Widen(b, handle) : b;
  const auto compute = widen ? at::kFloat : dtype;

  const int64_t batch = self.size(0);
  const int64_t rows = self.size(1);
  const int64_t inner = self.size(2);
  const int64_t cols = mat2.size(2);
  auto wide = at::empty({batch, rows, cols}, self.options().dtype(compute));

  // The batch case takes the whole product in one call when each operand is
  // either contiguous or a transpose of contiguous storage -- which covers
  // attention, where the second operand is k.transpose(-2, -1). CNNL describes
  // a transposed operand by its storage and applies the transpose itself, so
  // the descriptor is built over the contiguous view. A strided operand that is
  // neither keeps the per-slice loop below.
  bool a_batched_transposed = false;
  bool b_batched_transposed = false;
  at::Tensor a_use = aw;
  at::Tensor b_use = bw;
  if (!aw.is_contiguous() && aw.transpose(1, 2).is_contiguous()) {
    a_batched_transposed = true;
    a_use = aw.transpose(1, 2);
  }
  if (!bw.is_contiguous() && bw.transpose(1, 2).is_contiguous()) {
    b_batched_transposed = true;
    b_use = bw.transpose(1, 2);
  }
  if (a_use.is_contiguous() && b_use.is_contiguous() && batch > 0) {
    // With the transpose flag set the descriptor spans the storage, whose last
    // two axes are the logical matrix's in the other order.
    auto a3 = a_use.view({batch, a_batched_transposed ? inner : rows,
                           a_batched_transposed ? rows : inner});
    auto b3 = b_use.view({batch, b_batched_transposed ? cols : inner,
                           b_batched_transposed ? inner : cols});
    TensorDesc a3d, b3d, c3d;
    a3d.Set(a3);
    b3d.Set(b3);
    c3d.Set(wide);
    cnnlMatMulDescriptor_t bdesc = nullptr;
    CheckCnnl(cnnlCreateMatMulDescriptor(&bdesc), "cnnlCreateMatMulDescriptor");
    const bool flag = true;
    if (a_batched_transposed) {
      CheckCnnl(
          cnnlSetMatMulDescAttr(
              bdesc, CNNL_MATMUL_DESC_TRANSA, &flag, sizeof(flag)),
          "cnnlSetMatMulDescAttr (TRANSA)");
    }
    if (b_batched_transposed) {
      CheckCnnl(
          cnnlSetMatMulDescAttr(
              bdesc, CNNL_MATMUL_DESC_TRANSB, &flag, sizeof(flag)),
          "cnnlSetMatMulDescAttr (TRANSB)");
    }
    // A bare cnnlCreateMatMulAlgo leaves the algorithm untuned: measured 163 us
    // for a (32, 512, 64) x (32, 64, 512) product against 31 us once the
    // heuristic had chosen one. The heuristic is only exposed for the Ex
    // descriptor and answers with an Ex algorithm, which is the same underlying
    // handle cnnlBatchMatMulEx takes. Exactly one of these two handles exists at
    // the end, and each is destroyed by the call that made it -- swapping one
    // into the other's variable freed the same pointer twice.
    cnnlMatMulAlgo_t plain_algo = nullptr;
    cnnlMatMulExDescriptor_t hdesc = nullptr;
    cnnlMatMulExHeuristicResult_t hresult = nullptr;
    cnnlMatMulExAlgo_t tuned_algo = nullptr;
    cnnlMatMulAlgo_t algo_in_use = nullptr;
    size_t batch_workspace_size = 0;
    CheckCnnl(cnnlCreateMatMulExDescriptor(&hdesc), "cnnlCreateMatMulExDescriptor");
    CheckCnnl(
        cnnlCreateMatMulExHeuristicResult(&hresult),
        "cnnlCreateMatMulExHeuristicResult");
    const cnnlMatMulExPrefer_t no_preference = nullptr;
    int returned_algo = 0;
    const auto heuristic_status = cnnlGetMatMulExAlgoHeuristic(
        handle, hdesc, a3d.get(), b3d.get(), c3d.get(), c3d.get(),
        no_preference, /*requested_algo_count=*/1, &hresult, &returned_algo);
    if (heuristic_status == CNNL_STATUS_SUCCESS && returned_algo > 0) {
      CheckCnnl(cnnlCreateMatMulExAlgo(&tuned_algo), "cnnlCreateMatMulExAlgo");
      CheckCnnl(
          cnnlGetMatMulExHeuristicResult(
              hresult, tuned_algo, &batch_workspace_size),
          "cnnlGetMatMulExHeuristicResult (bmm)");
      algo_in_use = reinterpret_cast<cnnlMatMulAlgo_t>(tuned_algo);
    } else {
      CheckCnnl(cnnlCreateMatMulAlgo(&plain_algo), "cnnlCreateMatMulAlgo");
      algo_in_use = plain_algo;
    }
    at::Tensor batch_workspace;
    if (batch_workspace_size > 0) {
      batch_workspace = at::empty(
          {static_cast<int64_t>(batch_workspace_size)},
          self.options().dtype(at::kByte));
    }
    const float fast_one = 1.0f;
    const float fast_zero = 0.0f;
    const auto status = cnnlBatchMatMulEx(
        handle, bdesc, algo_in_use, &fast_one, a3d.get(), a3.const_data_ptr(),
        b3d.get(), b3.const_data_ptr(), &fast_zero, c3d.get(),
        wide.mutable_data_ptr(),
        batch_workspace_size > 0 ? batch_workspace.mutable_data_ptr() : nullptr,
        batch_workspace_size);
    if (tuned_algo != nullptr) {
      cnnlDestroyMatMulExAlgo(tuned_algo);
    }
    if (plain_algo != nullptr) {
      cnnlDestroyMatMulAlgo(plain_algo);
    }
    cnnlDestroyMatMulExHeuristicResult(hresult);
    cnnlDestroyMatMulExDescriptor(hdesc);
    cnnlDestroyMatMulDescriptor(bdesc);
    if (status == CNNL_STATUS_SUCCESS) {
      if (!widen) {
        return wide;
      }
      auto fast_result = at::empty({batch, rows, cols}, self.options());
      Narrow(wide, fast_result, handle);
      return fast_result;
    }
  }

  // CNNL's matmul is 2-D per call, so the batch axis is iterated here. Each
  // slice is a plain (rows, inner) x (inner, cols) product of contiguous
  // storage, which is exactly what the descriptor pair describes.
  const float one_f = 1.0f;
  const float zero_f = 0.0f;
  const void* alpha = static_cast<const void*>(&one_f);
  const void* beta = static_cast<const void*>(&zero_f);
  // Every batch slice has the same shape, so the descriptor, the algorithm and
  // its workspace are resolved once and reused. Doing that search per slice
  // measured 527 us for a 32-batch bmm, against 22 us for one multiply.
  const auto a_slice = aw[0];
  const auto b_slice = bw[0];
  auto out_slice = wide[0];
  TensorDesc ad, bd, cd;
  ad.Set(a_slice);
  bd.Set(b_slice);
  cd.Set(out_slice);
  cnnlMatMulExDescriptor_t desc = nullptr;
  CheckCnnl(cnnlCreateMatMulExDescriptor(&desc), "cnnlCreateMatMulExDescriptor");
  cnnlMatMulExAlgo_t algo = nullptr;
  CheckCnnl(cnnlCreateMatMulExAlgo(&algo), "cnnlCreateMatMulExAlgo");
  cnnlMatMulExHeuristicResult_t result_algo = nullptr;
  CheckCnnl(
      cnnlCreateMatMulExHeuristicResult(&result_algo),
      "cnnlCreateMatMulExHeuristicResult");
  cnnlMatMulExPrefer_t prefer{};
  int returned = 0;
  CheckCnnl(
      cnnlGetMatMulExAlgoHeuristic(
          handle, desc, ad.get(), bd.get(), cd.get(), cd.get(), prefer,
          /*requested_algo_count=*/1, &result_algo, &returned),
      "cnnlGetMatMulExAlgoHeuristic (bmm)");
  TORCH_CHECK(returned > 0, "flagos cambricon: no matmul algorithm for bmm");
  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetMatMulExHeuristicResult(result_algo, algo, &workspace_size),
      "cnnlGetMatMulExHeuristicResult");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  for (int64_t index = 0; index < batch; ++index) {
    CheckCnnl(
        cnnlMatMulEx_v2(
            handle, desc, algo, alpha, ad.get(),
            aw[index].const_data_ptr(), bd.get(), bw[index].const_data_ptr(),
            beta, cd.get(), wide[index].mutable_data_ptr(),
            workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
            workspace_size, cd.get(), wide[index].mutable_data_ptr()),
        "cnnlMatMulEx_v2 (bmm)");
  }
  cnnlDestroyMatMulExHeuristicResult(result_algo);
  cnnlDestroyMatMulExAlgo(algo);
  cnnlDestroyMatMulExDescriptor(desc);

  if (!widen) {
    return wide;
  }
  auto result = at::empty({batch, rows, cols}, self.options());
  Narrow(wide, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(BmmFn, bmm_dispatcher, Backend::kCambricon, BmmKernelCambricon);

at::Tensor CatKernelCambricon(const c10::IListRef<at::Tensor>& tensors, int64_t dim) {
  TORCH_CHECK(tensors.size() > 0, "flagos cambricon: cat needs one tensor");
  // Copied into a vector once -- a refcount bump each -- so every later read is
  // a plain lookup instead of an IListRef tag switch. materialize() is not used
  // because its elements are std::reference_wrapper, not tensors.
  std::vector<at::Tensor> parts;
  parts.reserve(tensors.size());
  for (const auto& t : tensors) {
    parts.emplace_back(t);
  }
  const at::Tensor& first = parts[0];
  TORCH_CHECK(
      first.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: cat requires device tensors");
  const int64_t rank = first.dim();
  const int64_t axis = dim < 0 ? dim + rank : dim;
  TORCH_CHECK(axis >= 0 && axis < rank, "flagos cambricon: cat got dim ", dim);
  for (const auto& t : parts) {
    TORCH_CHECK(
        t.device() == first.device() && t.scalar_type() == first.scalar_type(),
        "flagos cambricon: cat needs one device and one dtype");
  }
  if (!SupportedFloatDtype(first.scalar_type())) {
    std::vector<at::Tensor> host;
    host.reserve(parts.size());
    for (const auto& t : parts) {
      host.push_back(t.to(at::kCPU));
    }
    return at::cat(at::TensorList(host), dim).to(first.device());
  }

  auto sizes = first.sizes().vec();
  int64_t joined = 0;
  for (const auto& t : parts) {
    joined += t.size(axis);
  }
  sizes[axis] = joined;
  auto output = at::empty(sizes, first.options());
  if (output.numel() == 0) {
    return output;
  }

  CambriconDeviceGuard guard(first);
  const auto handle = HandleForDevice(static_cast<int>(first.device().index()));
  int64_t offset = 0;
  for (const auto& t : parts) {
    if (t.numel() == 0) {
      continue;
    }
    const auto src = t.contiguous();
    // Each input lands in a slice of the result. The slice keeps the result's
    // stride on every axis, so cnnlCopy_v2 is given a strided destination
    // descriptor and writes exactly the elements the slice covers.
    auto dst = output.narrow(axis, offset, t.size(axis));
    TensorDesc in_d, out_d;
    in_d.Set(src);
    out_d.SetStrided(dst);
    CheckCnnl(
        cnnlCopy_v2(
            handle, in_d.get(), src.const_data_ptr(), out_d.get(),
            dst.mutable_data_ptr(), nullptr, 0),
        "cnnlCopy_v2 (cat)");
    offset += t.size(axis);
  }
  return output;
}

REGISTER_IMPL_TO_DISPATCHER(CatFn, cat_dispatcher, Backend::kCambricon, CatKernelCambricon);


namespace {

::std::optional<at::Tensor> CloneKernelCambricon(
    const at::Tensor& self, ::std::optional<at::MemoryFormat> memory_format) {
  if (self.device().type() != c10::DeviceType::PrivateUse1) {
    return ::std::nullopt;
  }
  // FLAGOS_OP_clone=<backend> is the conf's per-op override, and clone has no
  // dispatcher slot for it to act on, so the hook reads it itself. Anything but
  // "cambricon" declines, which is how a build can be taken back to the ATen
  // route without being recompiled.
  {
    const char* want = std::getenv("FLAGOS_OP_clone");
    if (want != nullptr && std::strcmp(want, "cambricon") != 0) {
      return ::std::nullopt;
    }
  }
  if (!SupportedFloatDtype(self.scalar_type())) {
    return ::std::nullopt;
  }
  if (memory_format.has_value() &&
      *memory_format != at::MemoryFormat::Contiguous) {
    return ::std::nullopt;
  }
  // An empty tensor has nothing to gather, and describing it as a strided copy
  // is a call for a result that is already correct.
  if (self.numel() == 0) {
    return at::empty(self.sizes(), self.options());
  }

  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  auto result = at::empty(self.sizes(), self.options());
  TensorDesc in_desc, out_desc;
  // The source keeps its own strides: that is the whole point, and it is what
  // cnnlSetTensorDescriptorEx is for. It requires the innermost stride to be 1,
  // which is what a view of a dense tensor has.
  in_desc.SetStrided(self);
  out_desc.Set(result);
  CheckCnnl(
      cnnlCopy_v2(
          handle, in_desc.get(), self.const_data_ptr(), out_desc.get(),
          result.mutable_data_ptr(), nullptr, 0),
      "cnnlCopy_v2 (clone)");
  return result;
}

} // namespace (anon)

at::Tensor CumsumKernelCambricon(
    const at::Tensor& self, int64_t dim, std::optional<at::ScalarType> dtype) {
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: cumsum requires a device tensor");
  TORCH_CHECK(self.dim() > 0, "flagos cambricon: cumsum needs rank >= 1");
  const int64_t axis = dim < 0 ? dim + self.dim() : dim;
  TORCH_CHECK(
      axis >= 0 && axis < self.dim(),
      "flagos cambricon: cumsum got dim ", dim);
  const auto out_dtype = dtype.has_value() ? *dtype : self.scalar_type();
  // Integral accumulation would have to run in int64 to match aten's promotion;
  // this path is the float one, and anything else crosses to the host so the
  // answer stays exact. Models accumulate in float, so the fallback is cold.
  if (!SupportedFloatDtype(self.scalar_type()) ||
      !SupportedFloatDtype(out_dtype)) {
    return at::cumsum(self.to(at::kCPU), dim, dtype)
        .to(self.device());
  }

  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const auto input = self.contiguous();
  const auto wide = Widen(input, handle);
  auto wide_out = at::empty(self.sizes(), self.options().dtype(at::kFloat));

  TensorDesc in_d, out_d;
  in_d.Set(wide);
  out_d.Set(wide_out);
  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetCumsumWorkspaceSize(handle, in_d.get(), static_cast<int>(axis),
                                 &workspace_size),
      "cnnlGetCumsumWorkspaceSize");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  CheckCnnl(
      cnnlCumsum_v2(
          handle, in_d.get(), wide.const_data_ptr(), static_cast<int>(axis),
          /*exclusive=*/false, /*reverse=*/false, CNNL_NOT_PROPAGATE_NAN,
          out_d.get(), wide_out.mutable_data_ptr(),
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size),
      "cnnlCumsum_v2 (cumsum)");

  if (wide_out.scalar_type() == out_dtype) {
    return wide_out;
  }
  auto result = at::empty(self.sizes(), self.options().dtype(out_dtype));
  Narrow(wide_out, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(CumsumFn, cumsum_dispatcher, Backend::kCambricon, CumsumKernelCambricon);


at::Tensor DivScalarKernelCambricon(const at::Tensor& self, const at::Scalar& other) {
  // Divide by a constant is a multiply by its reciprocal, which is what the
  // reference backend does: on an MLU590 torch_mlu div is bit-identical to
  // x * (1/s) and not to a true divide, for both 3.7 and 0.1 in float32.
  // cnnlOpTensor has no divide at all.
  TORCH_CHECK(
      other.toDouble() != 0.0,
      "flagos cambricon: div.Scalar cannot divide by zero");
  return at::mul(self, 1.0 / other.toDouble());
}

REGISTER_IMPL_TO_DISPATCHER(DivScalarFn, div_scalar_dispatcher, Backend::kCambricon, DivScalarKernelCambricon);


at::Tensor& DivInplaceScalarKernelCambricon(at::Tensor& self, const at::Scalar& other) {
  // Dividing by a constant is a multiply by its reciprocal. cnnlOpTensor has no
  // divide and cnnlDiv_v3 wants a descriptor plus a workspace query per call --
  // the fixed per-launch cost this backend exists to remove.
  //
  // This matches the reference backend rather than approximating it: on an MLU590
  // torch_mlu's `div_(s)` is bit-identical to `x * (1/s)` and not to a true
  // divide, for both 3.7 and 0.1 in float32. So the reciprocal is the behaviour
  // to be consistent with, not a shortcut around it.
  TORCH_CHECK(
      other.toDouble() != 0.0,
      "flagos cambricon: div_.Scalar cannot divide by zero");
  self.mul_(1.0 / other.toDouble());
  return self;
}

REGISTER_IMPL_TO_DISPATCHER(DivInplaceScalarFn, div_inplace_scalar_dispatcher, Backend::kCambricon, DivInplaceScalarKernelCambricon);


at::Tensor EmbeddingKernelCambricon(
    const at::Tensor& weight, const at::Tensor& indices, int64_t padding_idx,
    bool scale_grad_by_freq, bool sparse) {
  TORCH_CHECK(
      !sparse, "flagos cambricon: embedding does not serve a sparse gradient");
  TORCH_CHECK(
      !scale_grad_by_freq,
      "flagos cambricon: embedding does not serve scale_grad_by_freq");
  TORCH_CHECK(
      weight.device() == indices.device(),
      "flagos cambricon: embedding needs both operands on one device");
  TORCH_CHECK(
      SupportedFloatDtype(weight.scalar_type()),
      "flagos cambricon: embedding does not serve ", weight.scalar_type());
  TORCH_CHECK(weight.dim() == 2, "flagos cambricon: embedding needs a 2-D weight");

  const auto w = weight.contiguous();
  auto idx = indices.contiguous();
  // cnnlEmbeddingForward takes int32 indices. aten allows int32 or int64, and
  // the cast is one small kernel over the index tensor.
  if (idx.scalar_type() != at::kInt) {
    idx = idx.to(at::kInt);
  }
  auto out_sizes = idx.sizes().vec();
  out_sizes.push_back(w.size(1));
  auto output = at::empty(out_sizes, w.options());
  if (output.numel() == 0) {
    return output;
  }
  CambriconDeviceGuard guard(w);
  const auto handle = HandleForDevice(static_cast<int>(w.device().index()));
  TensorDesc wd, id, od;
  wd.Set(w);
  id.Set(idx);
  od.Set(output);
  // max_norm and norm_type are pointers in the signature; both are null unless
  // the caller asked for renormalisation, which aten's embedding never does.
  CheckCnnl(
      cnnlEmbeddingForward_v2(
          handle, wd.get(), w.const_data_ptr(), id.get(), idx.const_data_ptr(),
          static_cast<int>(padding_idx), static_cast<const float*>(nullptr),
          static_cast<const float*>(nullptr), od.get(),
          output.mutable_data_ptr()),
      "cnnlEmbeddingForward_v2 (embedding)");
  return output;
}

REGISTER_IMPL_TO_DISPATCHER(EmbeddingFn, embedding_dispatcher, Backend::kCambricon, EmbeddingKernelCambricon);


at::Tensor EmbeddingDenseBackwardKernelCambricon(
    const at::Tensor& grad_output, const at::Tensor& indices,
    int64_t num_weights, int64_t padding_idx, bool scale_grad_by_freq) {
  TORCH_CHECK(
      grad_output.device().type() == c10::DeviceType::PrivateUse1 &&
          indices.device() == grad_output.device(),
      "flagos cambricon: embedding_dense_backward needs both tensors on the "
      "same flagos device");
  const auto dtype = grad_output.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: embedding_dense_backward does not serve ", dtype);
  TORCH_CHECK(
      indices.scalar_type() == at::kLong || indices.scalar_type() == at::kInt,
      "flagos cambricon: embedding indices must be int32 or int64, got ",
      indices.scalar_type());
  TORCH_CHECK(num_weights >= 0, "flagos cambricon: negative num_weights");
  TORCH_CHECK(
      num_weights <= kMaxNumWeights,
      "flagos cambricon: embedding tables larger than 2^24 rows are not served "
      "natively yet, got ",
      num_weights);

  const int64_t width = grad_output.dim() == 0 ? 0 : grad_output.size(-1);
  const int64_t rows = indices.numel();
  TORCH_CHECK(
      grad_output.numel() == rows * width,
      "flagos cambricon: embedding_dense_backward got ", grad_output.numel(),
      " gradient elements for ", rows, " indices of width ", width);

  auto result = at::zeros({num_weights, width}, grad_output.options());
  if (result.numel() == 0 || rows == 0) {{
    return result;
  }}

  CambriconDeviceGuard guard(grad_output);
  const auto handle =
      HandleForDevice(static_cast<int>(grad_output.device().index()));
  const auto grad_dense = grad_output.reshape({{rows, width}}).contiguous();
  auto flat = indices.reshape({{rows}});

  const bool active_padding = padding_idx >= 0 && padding_idx < num_weights;
  const int64_t discarded = num_weights;
  auto compare = flat;
  if (compare.scalar_type() == at::kInt) {{
    compare = compare.to(at::kLong);
  }}
  auto clamped = at::where(compare < 0, discarded, compare);
  clamped = at::where(clamped >= num_weights, discarded, clamped);
  if (active_padding) {{
    clamped = at::where(clamped == padding_idx, discarded, clamped);
  }}
  const auto target = NarrowIndices(clamped.contiguous(), handle).contiguous();

  const bool widen = ComputesInFloat32(dtype);
  auto wide = at::zeros(
      {{num_weights + 1, width}}, grad_output.options().dtype(at::kFloat));
  TensorDesc idx_desc;
  idx_desc.Set(target);
  TensorDesc grad_desc, out_desc;
  at::Tensor grad_fp32;
  if (widen) {
    grad_fp32 =
        at::empty({{rows, width}}, grad_output.options().dtype(at::kFloat));
    TensorDesc from, to;
    from.Set(grad_dense);
    to.Set(grad_fp32);
    CheckCnnl(
        cnnlCastDataType(
            handle, from.get(), grad_dense.const_data_ptr(),
            CastToFloat(dtype), to.get(), grad_fp32.mutable_data_ptr()),
        "cnnlCastDataType (embedding gradient)");
    grad_desc.Set(grad_fp32);
  } else {{
    grad_desc.Set(grad_dense);
  }}
  out_desc.Set(wide);

  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetEmbeddingBackwardWorkspaceSize(
          handle, grad_desc.get(), out_desc.get(), scale_grad_by_freq,
          &workspace_size),
      "cnnlGetEmbeddingBackwardWorkspaceSize");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {{static_cast<int64_t>(workspace_size)}},
        grad_output.options().dtype(at::kByte));
  }
  // Every index reaching CNNL is a valid table row: padding and out-of-range
  // rows already sit on the discarded slot, so no row is skipped here.
  CheckCnnl(
      cnnlEmbeddingBackward(
          handle, /*padding_idx=*/-1, scale_grad_by_freq, idx_desc.get(),
          target.const_data_ptr(), grad_desc.get(),
          widen ? grad_fp32.const_data_ptr() : grad_dense.const_data_ptr(),
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size, out_desc.get(), wide.mutable_data_ptr()),
      "cnnlEmbeddingBackward");

  const auto kept =
      wide.narrow(0, 0, num_weights).reshape({{num_weights, width}}).contiguous();
  if (!widen) {{
    return kept;
  }}
  result.copy_(kept);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(EmbeddingDenseBackwardFn, embedding_dense_backward_dispatcher, Backend::kCambricon, EmbeddingDenseBackwardKernelCambricon);

at::Tensor& FillInplaceScalarKernelCambricon(at::Tensor& self, const at::Scalar& value) {
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: fill_.Scalar requires a device tensor");
  const auto dtype = self.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(dtype) || dtype == at::kInt || dtype == at::kBool ||
          dtype == at::kLong,
      "flagos cambricon: fill_.Scalar does not serve ", dtype);
  if (self.numel() == 0) {
    return self;
  }
  // A CNNL descriptor cannot express rank zero, and `torch.ones([])` -- which
  // FlagGems' `all` builds as its reduction accumulator -- is exactly that. The
  // one element is written through a rank-one view of the same storage.
  if (self.dim() == 0) {
    auto flat = self.reshape({1});
    flat.fill_(value);
    return self;
  }
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));

  // The value travels in host memory. cnnlFill_v3 has a pointer mode that says
  // so; cnnlFill_v4 dropped the argument, and neither alternative to it works:
  // handed a host pointer v4 wrote nothing at all, and handed a one-element
  // device tensor the fill could read it after the temporary had been recycled,
  // which showed up as one call's value landing in the next one's buffer.
  //
  TensorDesc out_d;
  // cnnlFill_v3 honours a strided descriptor, so a view is written in place
  // rather than through an intermediate buffer.
  if (self.is_contiguous()) {
    out_d.Set(self);
  } else {
    out_d.SetStrided(self);
  }
  // The value is read by CNNL during the call, so it can live on the stack.
  // torch_mlu does exactly this: fill_internal.cpp passes
  // `(void*)&scalar_value` with CNNL_POINTER_MODE_HOST. Producing the bytes
  // through a heap tensor per call instead is what made this wrong -- `fill_(1)`
  // returned zero and `fill_(0)` returned the previous call's contents, because
  // the buffer was released while the queued fill still referred to it.
  AT_DISPATCH_ALL_TYPES_AND_COMPLEX_AND3(
      at::kBool, at::kBFloat16, at::kHalf, dtype, "fill_with_scalar", [&] {
        const auto fill_value = value.to<scalar_t>();
        CheckCnnl(
            cnnlFill_v3(handle, CNNL_POINTER_MODE_HOST, (void*)(&fill_value),
                        out_d.get(), self.mutable_data_ptr()),
            "cnnlFill_v3 (fill_.Scalar)");
      });
  return self;
}

REGISTER_IMPL_TO_DISPATCHER(FillInplaceScalarFn, fill_inplace_scalar_dispatcher, Backend::kCambricon, FillInplaceScalarKernelCambricon);


at::Tensor& LerpInplaceScalarKernelCambricon(
    at::Tensor& self, const at::Tensor& end, const at::Scalar& weight) {
  // One cnnlLerp call, the entry point the vendor uses
  // (torch_mlu/csrc/aten/operators/cnnl/internal/lerp_internal.cpp): self as a,
  // end as b, weight as w, ARRAY layouts throughout, and the same workspace
  // query.
  //
  // The two-pass spelling this replaces (mul by 1-w, then a scaled add) is
  // correct and needs no temporary, but it reads and writes the whole tensor
  // twice where this reads and writes it once. AdamW reaches lerp once per
  // parameter tensor every step, so for a 3072x1024 parameter that is one extra
  // 12 MB pass, each way.
  CambriconDeviceGuard guard(self);
  TORCH_CHECK(
      self.is_contiguous(),
      "flagos cambricon: lerp_.Scalar needs a contiguous destination");
  TORCH_CHECK(
      at::IntArrayRef(end.sizes()).equals(self.sizes()) && end.is_contiguous(),
      "flagos cambricon: lerp_.Scalar needs end to match the destination");
  if (self.numel() == 0) {
    return self;
  }
  const auto handle =
      HandleForDevice(static_cast<int>(self.device().index()));
  // cnnlLerp takes the weight as a tensor, not a host scalar, so the scalar is
  // materialised once. cnnlSetTensorDescriptor cannot describe rank zero, hence
  // the one-element reshape.
  auto weight_tensor =
      at::scalar_tensor(weight, self.options()).reshape({1});
  TensorDesc ad, bd, wd, od;
  ad.Set(self);
  bd.Set(end);
  wd.Set(weight_tensor);
  // Written into self's buffer: for the in-place form the destination is the
  // first operand, which is what the vendor's wrapper passes too.
  od.Set(self);
  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetLerpWorkspaceSize(
          handle, ad.get(), bd.get(), wd.get(), od.get(), &workspace_size),
      "cnnlGetLerpWorkspaceSize (lerp_.Scalar)");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        at::TensorOptions().dtype(at::kByte).device(self.device()));
  }
  CheckCnnl(
      cnnlLerp(
          handle, ad.get(), self.const_data_ptr(), bd.get(),
          end.const_data_ptr(), wd.get(), weight_tensor.const_data_ptr(),
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size, od.get(), self.mutable_data_ptr()),
      "cnnlLerp (lerp_.Scalar)");
  return self;
}

REGISTER_IMPL_TO_DISPATCHER(LerpInplaceScalarFn, lerp_inplace_scalar_dispatcher, Backend::kCambricon, LerpInplaceScalarKernelCambricon);


at::Tensor MeanKernelCambricon(
    const at::Tensor& self, std::optional<at::ScalarType> dtype_opt) {
  const at::ScalarType dtype = self.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: mean does not serve ", dtype);
  TORCH_CHECK(
      !dtype_opt.has_value() || SupportedFloatDtype(*dtype_opt),
      "flagos cambricon: mean does not serve the requested dtype");
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: mean requires a device tensor");
  TORCH_CHECK(self.numel() > 0, "flagos cambricon: mean of an empty tensor");

  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const bool widen = ComputesInFloat32(dtype);
  const auto input = self.contiguous();
  const auto wide_input = widen ? Widen(input, handle) : input;
  const auto compute = widen ? at::kFloat : dtype;

  // Reducing every axis leaves one element, so both sides are described at
  // their flattened rank rather than carrying the operand's shape through.
  std::vector<int64_t> flat_input_shape{input.numel()};
  auto flat_input = wide_input.reshape(flat_input_shape);
  auto flat_out = at::empty({1}, self.options().dtype(compute));
  std::vector<int> axes{0};

  cnnlReduceDescriptor_t desc = nullptr;
  CheckCnnl(cnnlCreateReduceDescriptor(&desc), "cnnlCreateReduceDescriptor");
  CheckCnnl(
      cnnlSetReduceDescriptor_v3(
          desc, axes.data(), 1, CNNL_REDUCE_AVG, ToCnnlDtype(compute),
          CNNL_NOT_PROPAGATE_NAN, CNNL_REDUCE_NO_INDICES, CNNL_32BIT_INDICES,
          /*p=*/0.0f, /*acc_sqrt=*/false),
      "cnnlSetReduceDescriptor_v3 (mean)");
  TensorDesc in_desc, out_desc;
  in_desc.Set(flat_input);
  out_desc.Set(flat_out);

  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetReduceOpWorkspaceSize_v2(
          handle, in_desc.get(), out_desc.get(), /*indices_desc=*/nullptr, desc,
          &workspace_size),
      "cnnlGetReduceOpWorkspaceSize_v2 (mean)");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  CheckCnnl(
      cnnlReduce_v2(
          handle, desc, in_desc.get(), flat_input.const_data_ptr(),
          /*alpha=*/nullptr, /*beta=*/nullptr,
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size, out_desc.get(), flat_out.mutable_data_ptr(),
          /*indices_desc=*/nullptr, /*indices=*/nullptr),
      "cnnlReduce_v2 (mean)");
  cnnlDestroyReduceDescriptor(desc);

  auto result = at::empty(
      {}, self.options().dtype(compute));
  if (compute == at::kFloat) {
    result.copy_(flat_out.reshape({}));
  } else {
    Narrow(flat_out, result, handle);
  }
  return result;
}

